<!-- This file is generated by AI. -->
<!--
  最近项目卡片 (开始界面)。
-->
<script lang="ts">
  import { joinPath } from '../lib/paths';
  import { useImageUrl } from '../lib/localImage.svelte';
  import { formatRelativeTime } from '../lib/recentProjects';
  import Icon from './Icon.svelte';

  export interface RecentProjectView {
    path: string;
    name: string;
    /** `Title_img` (仅文件名) */
    titleImg?: string;
    lastOpened: number;
    /** 目录是否还在 (被移动/删除的项目仍然留在列表里, 但要看得出来) */
    available: boolean;
  }

  let {
    project,
    onOpen,
    /** 操作菜单位置 (由"更多"按钮的实际位置算出) */
    onMenu,
    /** 右键该卡片 (由父组件处理, 因为菜单要挂在父级) */
    onCardContextMenu,
  }: {
    project: RecentProjectView;
    onOpen: () => void;
    onMenu: (position: { x: number; y: number }) => void;
    onCardContextMenu: (event: MouseEvent) => void;
  } = $props();

  /*
   * 封面图直接读 `game/background/<Title_img>` 的字节。
   * 目录不在时连读都不读 —— 那只会得到一个无意义的失败。
   */
  const cover = useImageUrl(() =>
    project.available && project.titleImg ? joinPath(project.path, 'game', 'background', project.titleImg) : null
  );
</script>

<div
  class="project-card"
  class:unavailable={!project.available}
  title={project.path}
  role="button"
  tabindex="0"
  onclick={onOpen}
  onkeydown={(event) => {
    if (event.key !== 'Enter' && event.key !== ' ') return;
    event.preventDefault();
    onOpen();
  }}
  oncontextmenu={(event) => onCardContextMenu(event)}
>
  <div class="project-cover">
    {#if cover.url}
      <img src={cover.url} alt="" draggable="false" />
    {:else}
      <span class="project-cover-placeholder" aria-hidden="true"><Icon name="Image" size={28} /></span>
    {/if}
    {#if !project.available}<span class="project-badge">位置不可用</span>{/if}
  </div>

  <div class="project-card-body">
    <h4 class="project-card-name">{project.name}</h4>
    <div class="project-card-row">
      <span class="project-card-time">{formatRelativeTime(project.lastOpened)}</span>
      <!--
        常驻的"更多"按钮: 悬浮才出现的小图标既难点中也看不见, 而所有操作本来就在右键菜单里,
        于是这里只留一个入口, 菜单内容与右键完全一致。
      -->
      <button
        type="button"
        class="project-card-menu"
        title="更多操作"
        aria-label="更多操作"
        onclick={(event) => {
          event.stopPropagation();
          const rect = event.currentTarget.getBoundingClientRect();
          onMenu({ x: rect.right, y: rect.bottom });
        }}
      >
        <Icon name="MoreVertical" />
      </button>
    </div>
  </div>
</div>
